const items = $input.all();
const withMeta = items.map((item) => {
  const json = item.json;
  const title = (json.child_page && json.child_page.title) || json.content || '';
  return { id: json.id, title: title, created_time: json.created_time || null };
});
const dated = withMeta.filter((entry) => entry.created_time);
const sourceList = dated.length > 0 ? dated : withMeta;
sourceList.sort((a, b) => (a.created_time && b.created_time) ? new Date(a.created_time) - new Date(b.created_time) : 0);
const recent = sourceList.slice(-7);
return recent.map((entry) => ({ json: entry }));

const markdownItems = $input.all();
const meta = $('Filter Recent Entries').all();
const sections = markdownItems.map((item, idx) => {
  const title = (meta[idx] && meta[idx].json.title) || 'Untitled';
  const markdown = item.json.markdown || '';
  return '## ' + title + '\n\n' + markdown;
});
const combined = sections.join('\n\n---\n\n');
return [{ json: { combinedMarkdown: combined, entryCount: sections.length } }];

const raw = $input.first().json;
let text = raw.content || raw.text || raw.output || raw.completion || '';
if (Array.isArray(text)) {
  text = text.map((block) => (block && block.text) || '').join('');
}
text = String(text).trim();
if (text.startsWith('```')) {
  text = text.replace(/^```[a-zA-Z]*\n/, '').replace(/```$/, '').trim();
}
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {};
}
const escapeHtml = (str) => String(str)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const buildCell = (stepNum, value) => {
  if (!value || !String(value).trim()) {
    return '<div class="cell empty" data-pain-step="' + stepNum + '">&mdash;</div>';
  }
  const safe = escapeHtml(String(value).trim());
  return '<div class="cell pain" data-pain-step="' + stepNum + '">\n' +
    '  <div class="cell-tag"><span class="emoji">\uD83D\uDE23</span>Pain point</div>\n' +
    '  <div class="clamp">\n    <ul>\n      <li>' + safe + '</li>\n    </ul>\n  </div>\n' +
    '  <button class="more-btn" type="button">More</button>\n</div>';
};
const cells = {};
for (let i = 1; i <= 6; i++) {
  cells['painCell' + i] = buildCell(i, parsed[String(i)] || '');
}
const now = new Date();
const lastIngested = now.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const next = new Date(now);
const daysUntilFriday = (5 - now.getDay() + 7) % 7 || 7;
next.setDate(now.getDate() + daysUntilFriday);
const weekday = next.toLocaleDateString('en-US', { weekday: 'short' });
const nextUpdate = weekday + ' ' + next.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const result = { lastIngested: lastIngested, nextUpdate: nextUpdate };
for (const key in cells) { result[key] = cells[key]; }
return [{ json: result }];

const fileJson = $input.first().json;
const encoded = fileJson.content || '';
const decoded = Buffer.from(encoded, 'base64').toString('utf-8');
const snippets = $('Build HTML Snippets').first().json;
let html = decoded;
for (let i = 1; i <= 6; i++) {
  const marker = 'PAIN_CELL:' + i;
  const pattern = new RegExp('<!-- ' + marker + ' -->[\\s\\S]*?<!-- /' + marker + ' -->', 'm');
  const replacement = '<!-- ' + marker + ' -->' + snippets['painCell' + i] + '<!-- /' + marker + ' -->';
  html = html.replace(pattern, replacement);
}
const lastPattern = /<!-- LAST_INGESTED -->[\s\S]*?<!-- \/LAST_INGESTED -->/m;
html = html.replace(lastPattern, '<!-- LAST_INGESTED --><b>' + snippets.lastIngested + '</b><!-- /LAST_INGESTED -->');
const nextPattern = /<!-- NEXT_UPDATE -->[\s\S]*?<!-- \/NEXT_UPDATE -->/m;
html = html.replace(nextPattern, '<!-- NEXT_UPDATE --><b>' + snippets.nextUpdate + '</b><!-- /NEXT_UPDATE -->');
return [{ json: { newContent: html } }];
